#include <cstdint>
#include <cstring>
#include <string>
#include <iostream>

// Minimal Slice class for testing
class Slice {
 public:
  Slice() : data_(nullptr), size_(0) {}
  Slice(const char* d, size_t n) : data_(d), size_(n) {}
  Slice(const std::string& s) : data_(s.data()), size_(s.size()) {}

  const char* data() const { return data_; }
  size_t size() const { return size_; }
  bool empty() const { return size_ == 0; }

  void remove_prefix(size_t n) {
    data_ += n;
    size_ -= n;
  }

  std::string ToString() const { return std::string(data_, size_); }

 private:
  const char* data_;
  size_t size_;
};

// Minimal GetVarint32 for testing
bool GetVarint32(Slice* input, uint32_t* value) {
  const char* p = input->data();
  const char* limit = p + input->size();
  uint32_t result = 0;
  for (int i = 0; i < 5; i++) {
    if (p >= limit) return false;
    uint32_t byte = *(reinterpret_cast<const uint8_t*>(p));
    p++;
    if (byte < 128) {
      *value = result | (byte << (7 * i));
      input->remove_prefix(p - input->data());
      return true;
    } else {
      result |= ((byte & 127) << (7 * i));
    }
  }
  return false;
}

// The function to implement
bool GetLengthPrefixedSlice(Slice* input, Slice* result) {
  uint32_t len;
  if (GetVarint32(input, &len)) {
    if (input->size() >= len) {
      *result = Slice(input->data(), len);
      input->remove_prefix(len);
      return true;
    }
  }
  return false;
}

// Test
int main() {
  std::string s;
  // Put empty string
  s.push_back(0);
  // Put "foo" (length 3)
  s.push_back(3);
  s.append("foo");
  // Put "bar" (length 3)
  s.push_back(3);
  s.append("bar");

  Slice input(s);
  Slice v;

  bool ok = GetLengthPrefixedSlice(&input, &v);
  std::cout << "Test 1 - empty string: " << (ok && v.ToString() == "" ? "PASS" : "FAIL") << std::endl;

  ok = GetLengthPrefixedSlice(&input, &v);
